import React, { useState, useEffect } from 'react';
import { supabase } from '../../supabaseClient';
import { validateArtistProfile } from '../../utils/contentFilter';
import { useAuth } from '../../context/AuthContext';

const SOFTWARE_OPTIONS = [
  'SketchUp',
  'V-Ray',
  '3ds Max',
  'Corona Renderer',
  'Unreal Engine',
  'Blender',
  'Lumion',
  'Twinmotion',
  'Enscape',
  'Other'
];

const ARCHITECTURE_STYLES = [
  'Contemporary',
  'Classic',
  'Modern',
  'Minimalist',
  'Industrial',
  'Rustic',
  'Eclectic',
  'Art Deco'
];

const PROJECT_TYPES = [
  'Facade',
  'Interiors',
  'Landscaping',
  'Urban',
  'Commercial',
  'Residential',
  'Industrial'
];

const ArtistProfile = () => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('');
  const [uploadingPhoto, setUploadingPhoto] = useState(false);
  const [validationErrors, setValidationErrors] = useState({});
  const [profile, setProfile] = useState({
    full_name: '',
    profile_photo: '',
    software: [],
    other_software: '',
    years_experience: 0,
    architecture_style: [],
    favorite_project_types: []
  });

  useEffect(() => {
    if (user) {
      loadProfile();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);

  const loadProfile = async () => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', user.id)
        .single();

      if (error) throw error;

      if (data) {
        setProfile({
          full_name: data.full_name || '',
          profile_photo: data.profile_photo || '',
          software: data.software || [],
          other_software: data.other_software || '',
          years_experience: data.years_experience || 0,
          architecture_style: data.architecture_style || [],
          favorite_project_types: data.favorite_project_types || []
        });
      }
    } catch (error) {
      console.error('Error loading profile:', error);
      setMessage('Error loading profile');
    } finally {
      setLoading(false);
    }
  };

  const handlePhotoUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Validate file type
    if (!file.type.startsWith('image/')) {
      setMessage('Please select a valid image');
      return;
    }

    // Validate file size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
      setMessage('Image must be at most 5MB');
      return;
    }

    setUploadingPhoto(true);
    setMessage('');

    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${user.id}/profile-photo.${fileExt}`;

      // Upload to Supabase Storage
      const { error: uploadError } = await supabase.storage
        .from('profile-photos')
        .upload(fileName, file, {
          cacheControl: '3600',
          upsert: true
        });

      if (uploadError) throw uploadError;

      // Get public URL
      const { data: urlData } = supabase.storage
        .from('profile-photos')
        .getPublicUrl(fileName);

      // Update profile with new photo URL
      const { error: updateError } = await supabase
        .from('profiles')
        .update({ profile_photo: urlData.publicUrl })
        .eq('id', user.id);

      if (updateError) throw updateError;

      setProfile(prev => ({ ...prev, profile_photo: urlData.publicUrl }));
      setMessage('✅ Photo updated successfully!');
    } catch (error) {
      console.error('Error uploading photo:', error);
      setMessage(`❌ Error uploading: ${error.message}`);
    } finally {
      setUploadingPhoto(false);
    }
  };

  const toggleArrayItem = (array, item) => {
    if (array.includes(item)) {
      return array.filter(i => i !== item);
    }
    return [...array, item];
  };

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true);
    setMessage('');
    setValidationErrors({});

    // Validate content
    const validation = validateArtistProfile(profile);
    if (!validation.isValid) {
      setValidationErrors(validation.errors);
      setMessage('❌ Please fix the errors before saving');
      setSaving(false);
      return;
    }

    try {
      // Check if this is first-time profile completion
      const { data: currentProfile } = await supabase
        .from('profiles')
        .select('approval_status, software')
        .eq('id', user.id)
        .single();

      const isFirstTimeCompletion = !currentProfile.software || currentProfile.software.length === 0;

      const updateData = {
        full_name: profile.full_name,
        software: profile.software,
        other_software: profile.other_software,
        years_experience: profile.years_experience,
        architecture_style: profile.architecture_style,
        favorite_project_types: profile.favorite_project_types
      };

      // If first time completion, set status to pending for review
      if (isFirstTimeCompletion) {
        updateData.approval_status = 'pending';
      }

      const { error } = await supabase
        .from('profiles')
        .update(updateData)
        .eq('id', user.id);

      if (error) throw error;

      if (isFirstTimeCompletion) {
        setMessage('✅ Profile submitted for review! Our team will review within 2 business days.');
      } else {
        setMessage('✅ Profile saved successfully!');
      }

      setTimeout(() => setMessage(''), 5000);

      // Reload profile to get updated approval_status
      await loadProfile();
    } catch (error) {
      console.error('Error saving profile:', error);
      setMessage(`❌ Error saving: ${error.message}`);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <div className="loading">Loading profile...</div>;
  }

  return (
    <div className="artist-profile-editor">
      <h2 className="section-title">My Professional Profile</h2>
      <p className="subtitle">Configure your information and specialties</p>

      {message && (
        <div className={`message ${message.includes('✅') ? 'success' : 'error'}`}>
          {message}
        </div>
      )}

      <div className="profile-editor-grid">
        {/* Left Column - Photo */}
        <div className="profile-photo-section">
          <div className="profile-photo-container">
            {profile.profile_photo ? (
              <img
                src={profile.profile_photo}
                alt="Profile"
                className="profile-photo-preview"
              />
            ) : (
              <div className="profile-photo-placeholder">
                <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                </svg>
              </div>
            )}
          </div>

          <label className="btn-secondary upload-photo-btn">
            {uploadingPhoto ? 'Uploading...' : 'Change Photo'}
            <input
              type="file"
              accept="image/*"
              onChange={handlePhotoUpload}
              disabled={uploadingPhoto}
              style={{ display: 'none' }}
            />
          </label>
          <p className="photo-hint">JPG, PNG or GIF (max 5MB)</p>
        </div>

        {/* Right Column - Form */}
        <div className="profile-form-section">
          <form onSubmit={handleSave}>
            {/* Name */}
            <div className="form-group">
              <label className="form-label">Full Name *</label>
              <input
                type="text"
                value={profile.full_name}
                onChange={(e) => setProfile({ ...profile, full_name: e.target.value })}
                placeholder="Your full name"
                required
                className={`form-input ${validationErrors.full_name ? 'error' : ''}`}
              />
              {validationErrors.full_name && (
                <p className="form-error">{validationErrors.full_name}</p>
              )}
            </div>

            {/* Years of Experience */}
            <div className="form-group">
              <label className="form-label">Years of 3D Experience *</label>
              <input
                type="number"
                min="0"
                max="50"
                value={profile.years_experience}
                onChange={(e) => setProfile({ ...profile, years_experience: parseInt(e.target.value) || 0 })}
                placeholder="Ex: 5"
                required
                className="form-input"
              />
              <p className="form-hint">How many years have you worked with 3D rendering?</p>
            </div>

            {/* Software */}
            <div className="form-group">
              <label className="form-label">Software I Use *</label>
              <div className="checkbox-grid">
                {SOFTWARE_OPTIONS.map((software) => (
                  <label key={software} className="checkbox-label">
                    <input
                      type="checkbox"
                      checked={profile.software.includes(software)}
                      onChange={() => setProfile({
                        ...profile,
                        software: toggleArrayItem(profile.software, software)
                      })}
                      className="checkbox-input"
                    />
                    <span>{software}</span>
                  </label>
                ))}
              </div>
              <p className="form-hint">Select all that apply</p>
            </div>

            {/* Other Software */}
            {profile.software.includes('Other') && (
              <div className="form-group">
                <label className="form-label">What other software?</label>
                <input
                  type="text"
                  value={profile.other_software}
                  onChange={(e) => setProfile({ ...profile, other_software: e.target.value })}
                  placeholder="Ex: Maya, Cinema 4D, etc."
                  className={`form-input ${validationErrors.other_software ? 'error' : ''}`}
                />
                {validationErrors.other_software && (
                  <p className="form-error">{validationErrors.other_software}</p>
                )}
              </div>
            )}

            {/* Architecture Style */}
            <div className="form-group">
              <label className="form-label">Architecture Styles *</label>
              <div className="checkbox-grid">
                {ARCHITECTURE_STYLES.map((style) => (
                  <label key={style} className="checkbox-label">
                    <input
                      type="checkbox"
                      checked={profile.architecture_style.includes(style)}
                      onChange={() => setProfile({
                        ...profile,
                        architecture_style: toggleArrayItem(profile.architecture_style, style)
                      })}
                      className="checkbox-input"
                    />
                    <span>{style}</span>
                  </label>
                ))}
              </div>
              <p className="form-hint">Which styles do you specialize in?</p>
            </div>

            {/* Favorite Project Types */}
            <div className="form-group">
              <label className="form-label">Favorite Project Types *</label>
              <div className="checkbox-grid">
                {PROJECT_TYPES.map((type) => (
                  <label key={type} className="checkbox-label">
                    <input
                      type="checkbox"
                      checked={profile.favorite_project_types.includes(type)}
                      onChange={() => setProfile({
                        ...profile,
                        favorite_project_types: toggleArrayItem(profile.favorite_project_types, type)
                      })}
                      className="checkbox-input"
                    />
                    <span>{type}</span>
                  </label>
                ))}
              </div>
              <p className="form-hint">What types of projects do you most enjoy doing?</p>
            </div>

            <div className="form-actions">
              <button
                type="submit"
                disabled={saving}
                className="btn-primary"
              >
                {saving ? 'Saving...' : 'Save Changes'}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default ArtistProfile;